// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        amount = bound(amount, 1, address(this).balance == 0 ? 0 : address(this).balance);
        vm.assume(amount > 0);
        vm.deal(address(this), amount + 1 ether);
        // fund the contract via its payable fallback
        (bool ok, ) = address(c).call{value: amount}("");
        assertTrue(ok);

        uint256 before = address(c).balance;
        vm.deal(address(this), 1 ether);
        c.withdrawAll();
        uint256 afterB = address(c).balance;

        // General rule: withdrawAll actually transfers the whole balance out;
        // the owner (this test) receives it, so C's balance drops to zero.
        assertTrue(afterB + before == before, "withdraw must reduce contract balance by the withdrawn amount");
        assertTrue(afterB < before, "withdraw must actually move funds out of the contract");
    }

    receive() external payable {}
}
